/* build-bundle.mjs — assemble the CSSON JS bundle for QuickJS, emit a C header.
 *
 *   node tools/build-bundle.mjs <out.h>
 *
 * Steps: esbuild-bundle our TypeScript (ts/csson.ts) → IIFE that sets
 * globalThis.csson (PostCSS bundled in; 4 node-builtin imports stubbed since the
 * parse/stringify path never calls them); prepend csstree's self-contained dist
 * (the @property lexer + mdn-data) and bridge it to globalThis; emit the whole
 * thing as a NUL-terminated C byte array for the facade to JS_Eval. */
import { build } from "esbuild";
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, "..");
const out = process.argv[2] || join(root, "csson_bundle.h");

const shim = (f) => join(here, "shims", f);
const result = await build({
  entryPoints: [join(root, "ts/csson.ts")],
  bundle: true,
  format: "iife",
  platform: "neutral",
  target: "es2020",
  legalComments: "none",
  alias: {
    picocolors: shim("pico.js"),
    fs: shim("empty.js"),
    url: shim("empty.js"),
    path: shim("path.js"),
    "source-map-js": shim("empty.js"),
  },
  write: false,
});
const ours = result.outputFiles[0].text;

const csstreeDist = readFileSync(join(root, "node_modules/css-tree/dist/csstree.js"), "utf8");
const app = csstreeDist + "\nglobalThis.csstree=csstree;\n" + ours;

const bytes = Buffer.from(app, "utf8");
let h = "/* generated by tools/build-bundle.mjs — do not edit */\n";
h += "static const unsigned char csson_bundle[] = {";
for (let i = 0; i < bytes.length; i++) h += (i % 20 === 0 ? "\n  " : "") + bytes[i] + ",";
h += "0\n};\n";
h += `static const unsigned int csson_bundle_len = ${bytes.length};\n`;
writeFileSync(out, h);
console.error(`bundle: ${(bytes.length / 1024).toFixed(0)} KB -> ${out}`);
